using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime
{
 public sealed class StorageView:MonoBehaviour
 {
  GameRuntime game;Text status;Transform body;string lastExport;AtomicSaveStore.Candidate selected;bool De=>game.State.Settings.language=="de";
  public void Initialize(GameRuntime runtime){game=runtime;Build();}
  Text Paragraph(string name,string text){var t=WorkshopUIFactory.Label(name,body,text,14,54);t.alignment=TextAnchor.UpperLeft;t.supportRichText=false;t.GetComponent<LayoutElement>().minHeight=54;t.GetComponent<LayoutElement>().preferredHeight=-1;return t;}
  void Try(Action action){try{action();}catch(Exception e){status.text=e.Message;}}
  void Build(){WorkshopUIFactory.Clear(transform);body=transform;WorkshopUIFactory.Label("StorageTitle",body,De?"Spielstände und Berichte":"Saves and reports",18,54);status=Paragraph("StorageStatus",game.Writable?(De?"Aktiver Stand ist schreibbar.":"Active save is writable."):(De?"Aktiver Stand gesperrt. Originale bleiben erhalten.":"Active save is locked. Originals are preserved."));Paragraph("StoragePath",game.SavePath);var export=WorkshopUIFactory.Button("ExportUnitySave",body,SettingsRules.Text(game.State.Settings.language,"ui:exportSave"),()=>Try(()=>{string dir=Path.Combine(Path.GetDirectoryName(game.SavePath),"Exports");lastExport=Path.Combine(dir,"unity-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")+".json");game.Storage.Export(game.State,lastExport);status.text=lastExport;}));export.interactable=game.HasReadableState;
   WorkshopUIFactory.Button("CopyExportJson",body,De?"Letzten Export in Zwischenablage kopieren":"Copy last export to clipboard",()=>Try(()=>{if(lastExport==null)throw new InvalidOperationException(De?"Zuerst exportieren.":"Export first.");GUIUtility.systemCopyBuffer=File.ReadAllText(lastExport);status.text=De?"Export kopiert.":"Export copied.";}));WorkshopUIFactory.Button("ShowExportFolder",body,De?"Exportordner öffnen":"Open export folder",()=>Try(()=>{string dir=Path.Combine(Path.GetDirectoryName(game.SavePath),"Exports");Directory.CreateDirectory(dir);Application.OpenURL(new Uri(dir+Path.DirectorySeparatorChar).AbsoluteUri);}));
   WorkshopUIFactory.Label("RecoveryTitle",body,"Recovery",17,54);Paragraph("RecoveryExplanation",De?"Datei prüfen, Vorschau ansehen und ausdrücklich wiederherstellen. Vor dem Austausch werden Quelle, Hauptstand, Backup und Pendingdatei unverändert gesichert.":"Validate a file, inspect the preview and explicitly restore it. Source, main, backup and pending files are preserved before replacement.");WorkshopUIFactory.Button("OpenWebConverter",body,De?"Lokalen Web-Konverter öffnen":"Open local web converter",()=>Application.OpenURL(new Uri(Path.Combine(Application.streamingAssetsPath,"UnityWebImport.html")).AbsoluteUri));foreach(string path in game.Storage.RecoveryFiles()){string file=path;WorkshopUIFactory.Button("Inspect-"+Path.GetFileName(file),body,Path.GetFileName(file),()=>Select(file));}var root=WorkshopUIFactory.Node("RecoveryPathInput",body,typeof(Image),typeof(InputField));WorkshopUIFactory.Size(root,64);root.GetComponent<Image>().color=new Color(.1f,.2f,.25f);var text=WorkshopUIFactory.Label("Value",root.transform,"",14);DestroyImmediate(text.GetComponent<LayoutElement>());WorkshopUIFactory.Fill(text.rectTransform);var input=root.GetComponent<InputField>();input.textComponent=text;input.lineType=InputField.LineType.MultiLineNewline;input.text=game.SavePath;WorkshopUIFactory.Button("InspectRecoveryPath",body,De?"Dateipfad prüfen":"Validate file path",()=>Select(input.text));
   WorkshopUIFactory.Button("InspectWebTransfer",body,De?"Web-Transferdatei prüfen":"Validate web transfer file",()=>Try(()=>{var imported=UnityWebImport.InspectFile(input.text);string dir=Path.Combine(Path.GetDirectoryName(game.SavePath),"ImportOriginals");Directory.CreateDirectory(dir);string stamp=Guid.NewGuid().ToString("N");File.Copy(input.text,Path.Combine(dir,"web-transfer-original-"+stamp+".json"),false);string candidate=Path.Combine(dir,"validated-native-"+stamp+".json");game.Storage.Export(imported,candidate);Select(candidate);status.text="Web v"+imported.Web.sourceVersion+" · SHA256 "+imported.Web.Hash()+"\n"+string.Join("\n",imported.Web.notes);}));Paragraph("RecoveryPreview","");var confirm=WorkshopUIFactory.Button("ConfirmRecovery",body,De?"Ausgewählten Stand nach Originalkopie wiederherstellen":"Restore selected save after preserving originals",()=>Try(()=>{if(selected?.Valid!=true)throw new InvalidOperationException("No valid selection");game.RecoverSave(selected.Path,selected.Hash);}));confirm.interactable=false;
   if(game.State.Web.present){Paragraph("PreservedWebInfo","Web v"+game.State.Web.sourceVersion+" · SHA256 "+game.State.Web.Hash());WorkshopUIFactory.Button("ExportPreservedWebOriginal",body,"Web · Original JSON",()=>Try(()=>{string dir=Path.Combine(Path.GetDirectoryName(game.SavePath),"Exports");Directory.CreateDirectory(dir);lastExport=Path.Combine(dir,"web-original-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(lastExport,game.State.Web.original);status.text=lastExport;}));WorkshopUIFactory.Button("ExportPreservedWebNormalized",body,"Web · Normalized JSON / historical data",()=>Try(()=>{string dir=Path.Combine(Path.GetDirectoryName(game.SavePath),"Exports");Directory.CreateDirectory(dir);lastExport=Path.Combine(dir,"web-normalized-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(lastExport,game.State.Web.normalized);status.text=lastExport;}));}ShowReturn();foreach(var receipt in game.State.Journal.returns.Reverse()){var saved=receipt;WorkshopUIFactory.Button("ViewReturn-"+saved.id,body,"#"+saved.id+" · "+Date(saved.through)+" · "+saved.context,()=>{game.Act(s=>{var next=s.Copy();next.Return=saved.Copy();return next;});Build();}).interactable=game.Writable;}ShowHistory();WorkshopUIFactory.Button("ExportLocalDiagnostics",body,De?"Lokalen Diagnosebericht exportieren":"Export local diagnostics",()=>Try(()=>{string dir=Path.Combine(Path.GetDirectoryName(game.SavePath),"Exports");Directory.CreateDirectory(dir);string path=Path.Combine(dir,"diagnostics-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(path,JsonUtility.ToJson(new Diagnostics{unity=Application.unityVersion,platform=Application.platform.ToString(),operatingSystem=SystemInfo.operatingSystem,build=Application.version,writable=game.Writable,savePath=game.SavePath,readable=game.HasReadableState,scope="file-runtime",nativeWatchdogImplemented=false,measurements=game.Diagnostics.Copy(),state=game.HasReadableState?StateData.From(game.State):null,events=game.HasReadableState?game.State.Journal.Copy(true):null,lastReturn=game.HasReadableState?game.State.Return.Copy():null},true));lastExport=path;status.text=path;}));
  }
  void ShowHistory(){var h=game.State.Journal.history;Paragraph("BalanceHistorySummary","Balance · "+h.runs.Length+" runs · "+h.archivedRuns+" archived · "+game.State.Journal.returns.Length+" return receipts\n"+(h.current==null?"No measured current run":h.current.observedFrom+" · active "+h.current.activeSeconds+" s · offline "+h.current.offlineSeconds+" s"));WorkshopUIFactory.Button("ExportBalanceHistory",body,De?"Balancehistorie exportieren":"Export balance history",()=>Try(()=>{string dir=Path.Combine(Path.GetDirectoryName(game.SavePath),"Exports");Directory.CreateDirectory(dir);lastExport=Path.Combine(dir,"balance-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(lastExport,JsonUtility.ToJson(game.State.Journal.history.Copy(true),true));status.text=lastExport;})).interactable=game.HasReadableState;foreach(var run in h.runs)Paragraph("BalanceRun-"+run.cycle+"-"+run.run,"#"+run.cycle+" / "+run.run+" · "+run.kind+" · "+Date(run.observedFrom)+" → "+Date(run.endedAt)+"\nCredits: "+ScientificNumber.FromData(run.credits)+" · Data: "+ScientificNumber.FromData(run.data)+" · INT: "+ScientificNumber.FromData(run.intReward)+" · Axiom: "+ScientificNumber.FromData(run.axiomReward)+"\n"+(run.partial?"PARTIAL · measured only since native observation":"Measured native run"));}
  void Select(string file){Try(()=>{selected=game.Storage.Inspect(file);var label=transform.Find("RecoveryPreview").GetComponent<Text>();label.text=selected.Message+"\n"+file;if(selected.Valid)label.text+="\n"+Date(selected.State.SavedAt)+"\nCredits: "+selected.State.Credits+" · Items: "+selected.State.Workshop.inventory.Length+" · INT: "+selected.State.Prestige.Total;transform.Find("ConfirmRecovery").GetComponent<Button>().interactable=selected.Valid;});}
  static string Date(double ms){try{return DateTimeOffset.FromUnixTimeMilliseconds((long)ms).ToLocalTime().ToString("G");}catch{return ms.ToString("R")+" UTC ms";}}
  void ShowReturn(){var r=game.State.Return;Paragraph("ReturnTitle",De?"Tatsächlicher Rückkehrbericht":"Measured return report");if(!r.hasReport){Paragraph("ReturnEmpty",De?"Noch keine Rückkehr gemessen.":"No return measured yet.");return;}string F(NumberData n)=>NumberFormatting.Format(ScientificNumber.FromData(n),game.State.Settings.numberFormat);Paragraph("ReturnMeasurements",Date(r.from)+" → "+Date(r.through)+"\n"+(De?"Abwesend / angerechnet / verfallen: ":"Away / credited / discarded: ")+r.elapsed.ToString("F2")+" / "+r.credited.ToString("F2")+" / "+r.discarded.ToString("F2")+" s\n"+SettingsRules.Text(game.State.Settings.language,"return:gross")+"\nCredits: "+F(r.credits)+" · Data: "+F(r.data)+" · Insight: "+F(r.insight)+"\nTraining: "+r.training+" · Research: "+r.research+" · Analyses: "+r.analyses+" · Crafting: "+r.crafted+"\nPrestige: "+r.prestiges+" · Axioms: "+r.axioms+"\n"+SettingsRules.Text(game.State.Settings.language,"return:available")+"\nCredits: "+F(r.availableCredits)+" · Data: "+F(r.availableData)+"\nContext: "+r.context+" · #"+r.id+"\nComponents: "+string.Join(" · ",r.components.Select((amount,i)=>new{amount,i}).Where(x=>x.amount>0).Select(x=>ItemBalance.ComponentNames[x.i]+" "+x.amount))+"\nFragments: "+r.fragments+" · Research fragments: "+r.researchFragments+"\nItems: "+string.Join(" · ",r.items.Select(item=>item.type+" #"+item.id+" Lv."+item.level)));foreach(var action in GuidanceRules.Return(game.State)){var selectedAction=action;WorkshopUIFactory.Button("ReturnAction-"+action.Kind,body,SettingsRules.Text(game.State.Settings.language,"return:"+action.Kind),()=>game.NavigateTo(selectedAction.Tab,selectedAction.Element,selectedAction.Mode));}var read=WorkshopUIFactory.Button("ReadReturnReport",body,De?"Bericht als gelesen markieren":"Mark report as read",()=>{game.Act(s=>{var n=s.Copy();n.Return.read=true;n.Journal.returns=n.Journal.returns.Select(r=>{if(r.id!=n.Return.id)return r;var copy=r.Copy();copy.read=true;return copy;}).ToArray();return n;});status.text=De?"Lesestatus gespeichert; keine zusätzliche Vergabe.":"Read state saved; no additional reward.";});read.interactable=game.Writable&&!r.read;}
  [Serializable]sealed class Diagnostics{public string unity,platform,operatingSystem,build,savePath;public bool writable,readable,nativeWatchdogImplemented;public string scope;public LocalDiagnostics measurements;public StateData state;public LocalJournal events;public ReturnReceipt lastReturn;}
 }
}
